  return JSON.parse(text.replace(/\/\/.*$/gm, ''));
}

solutionCodeJson.code:
// Bài 1.2 — JSONC: duyệt từng ký tự, nhớ đang ở trong chuỗi hay không
function parseJsonc(text) {
  let out = '';
  let inString = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (inString) {
      out += ch;
      if (ch === '\\') { out += text[i + 1]; i++; }   // ký tự thoát: chép nguyên cặp
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') { inString = true; out += ch; continue; }
    if (ch === '/' && text[i + 1] === '/') {              // chú thích một dòng
      while (i < text.length && text[i] !== '\n') i++;
      out += '\n';
      continue;
    }
    if (ch === '/' && text[i + 1] === '*') {              // chú thích khối
      const end = text.indexOf('*/', i + 2);
      i = end === -1 ? text.length : end + 1;
      continue;
    }
    if (ch === ',') {                                       // dấu phẩy thừa?
      let j = i + 1;
      while (j < text.length && /\s/.test(text[j])) j++;
      if (text[j] === '}' || text[j] === ']') continue;
    }
    out += ch;
  }
  return JSON.parse(out);
}

